('3bc0fe97-d607-5c66-8784-2bdfb55e7506', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di destana "Siyabend û Xecê" de mijara sereke çi ye?', 'Şerê du eşîran', 'Evîna trajîk a li çiyê', 'Rêwîtiya bazirganekî', 'Damezrandina gundekî', 'B', 'Siyabend û Xecê evîndarên destanê ne; çîrok bi trajediyê li çiyê diqede.', 'Siyabend û Xecê evîndarên destanê ne; çîrok bi trajediyê li çiyê diqede.', 'Siyabend ile Xecê destanın âşıklarıdır; hikâye dağda trajediyle biter.', 5, true, 'multiple_choice', NULL, NULL, 'Folklor û kevneşopiya kurdî', 'Ordîxanê Celîl & Celîlê Celîl, Zargotina Kurda; Encyclopaedia Iranica — Newruz', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_cand_0033
('917cd285-6c60-58ed-b2f1-022cbcf355a4', (select id from categories where name = 'Çand'), 'ku-kmr', 'Rast e an şaş e: Govend bi gelemperî bi destgirtin tê lîstin.', 'Rast', 'Şaş', '-', '-', 'A', 'Di govendê de mirov bi destan an bi qolan hev digirin.', 'Di govendê de mirov bi destan an bi qolan hev digirin.', 'Halayda eller ya da kollar tutulur.', 2, true, 'true_false', NULL, NULL, 'Folklor û kevneşopiya kurdî', 'Ordîxanê Celîl & Celîlê Celîl, Zargotina Kurda; Encyclopaedia Iranica — Newruz', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_cand_0034
('28250ad8-6ac2-5f70-bed6-12528eb3ae6c', (select id from categories where name = 'Çand'), 'ku-kmr', 'Xwarina "serê salê" an xwarinên cejnê bi giştî çima girîng in?', 'Ji ber ku erzan in', 'Ji ber ku zû tên çêkirin', 'Ji ber ku tenê ji bo mêvanan in', 'Ji ber ku civak û malbatê tînin cem hev', 'D', 'Sifreya cejnê fonksiyoneke civakî digire: xizm û cîran tên cem hev.', 'Sifreya cejnê fonksiyoneke civakî digire: xizm û cîran tên cem hev.', 'Bayram sofrası toplumsal bir işlev taşır: akraba ve komşuyu bir araya getirir.', 3, true, 'multiple_choice', NULL, NULL, 'Folklor û kevneşopiya kurdî', 'Ordîxanê Celîl & Celîlê Celîl, Zargotina Kurda; Encyclopaedia Iranica — Newruz', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_cand_0035
('1a6fe567-825e-59b5-bbc3-aa1790ef6ff0', (select id from categories where name = 'Çand'), 'ku-kmr', '"Hevrîşk" an "hevrîşim" di destkariya kurdî de çi ye?', 'amûra kevneşopî ya dişibe bilûrê', 'hevrîşim (ipek) — ji bo tevn û xemlê', 'mêvan bi rûmet pêşwazîkirin', 'fîgura mîtolojîk a çanda rojhilat', 'B', 'Hevrîşim di tevn û cilûbergên xemilandî de tê bikaranîn.', 'Hevrîşim di tevn û cilûbergên xemilandî de tê bikaranîn.', 'İpek, dokuma ve süslü giysilerde kullanılır.', 4, true, 'multiple_choice', NULL, NULL, 'Folklor û kevneşopiya kurdî', 'Ordîxanê Celîl & Celîlê Celîl, Zargotina Kurda; Encyclopaedia Iranica — Newruz', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_cand_0036
('e01ffe19-6925-5230-addb-878350c5c7c5', (select id from categories where name = 'Çand'), 'ku-kmr', '"Tevn" di destkariya kurdî de çi ye?', 'amûra hûnandina xalîçe û bêrîkan', 'danûstandina civakî û biryardayîn', 'amûra kevneşopî ya dişibe bilûrê', 'bi hunera destan ve girêdayî ye', 'A', 'Tevn ji bo hûnandina xalîçe, kilîm û tûrikan tê bikaranîn.', 'Tevn ji bo hûnandina xalîçe, kilîm û tûrikan tê bikaranîn.', 'Tezgâh; halı, kilim ve heybe dokumak için kullanılır.', 2, true, 'multiple_choice', NULL, NULL, 'Folklor û kevneşopiya kurdî', 'Ordîxanê Celîl & Celîlê Celîl, Zargotina Kurda; Encyclopaedia Iranica — Newruz', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_cand_0037
('c1b17c99-b7ab-50e0-aa6a-f194c9889fe2', (select id from categories where name = 'Çand'), 'ku-kmr', 'Xalîçe û kilîmên kurdî bi giştî bi çi tên xemilandin?', 'Wêneyên fotografî', 'Motîfên hêjmarî û sembolîk', 'Nivîsên dirêj', 'Rengên tenê reş û spî', 'B', 'Her motîf xwedî wateyekê ye: bereket, parastin, malbat.', 'Her motîf xwedî wateyekê ye: bereket, parastin, malbat.', 'Her motifin bir anlamı vardır: bereket, koruma, aile.', 3, true, 'multiple_choice', NULL, NULL, 'Folklor û kevneşopiya kurdî', 'Ordîxanê Celîl & Celîlê Celîl, Zargotina Kurda; Encyclopaedia Iranica — Newruz', 'approved', 'Kurmancî', 2, now()), -- yerel: edit_cand_0038
('5c5039bc-588d-539b-8d1f-4b5369d6c746', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di destana Mem û Zînê de kesê fesad ê ku nahêle Mem û Zîn bigihîjin hev kî ye?', 'Arif', 'Siyabend', 'Beko', 'Tacdîn', 'C', 'Beko dergevanê mîr e û bi fesadiya xwe nahêle Mem û Zîn bigihîjin hev; lewma di nav kurdan de navê wî bûye sembola fesadî û xiyanetê.', 'Beko dergevanê mîr e û bi fesadiya xwe nahêle Mem û Zîn bigihîjin hev; lewma di nav kurdan de navê wî bûye sembola fesadî û xiyanetê.', 'Beko mirin kapıcısıdır ve fesatlığıyla Mem ile Zîn''in kavuşmasını engeller; bu yüzden adı Kürtler arasında fesatlık ve ihanetin simgesi olmuştur.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Mem_and_Zin', 'Mem and Zin - Wikipedia', 'https://en.wikipedia.org/wiki/Mem_and_Zin', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_001
('92bf1109-5f46-51ad-87f8-e33cd9f42299', (select id from categories where name = 'Çand'), 'ku-kmr', 'Bûyerên destana Mem û Zîna Ehmedê Xanî li kîjan bajarî derbas dibin?', 'Amed', 'Bedlîs', 'Cizîr', 'Wan', 'C', 'Mem û Zîn li Cizîra Botan, paytexta Mîr Zeynedîn, derbas dibe; gora her du evîndaran jî îro li Cizîrê ye.', 'Mem û Zîn li Cizîra Botan, paytexta Mîr Zeynedîn, derbas dibe; gora her du evîndaran jî îro li Cizîrê ye.', 'Mem û Zîn, Mîr Zeynedîn''in başkenti Cizre''de (Cizîra Botan) geçer; iki sevgilinin mezarı da bugün Cizre''dedir.', 1, true, 'multiple_choice', NULL, 'https://wikisource.org/wiki/Mem_%C3%BB_Z%C3%AEn_(naverok)', 'Mem û Zîn (naverok) - Wikisource', 'https://wikisource.org/wiki/Mem_%C3%BB_Z%C3%AEn_(naverok)', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_002
('246499d1-e27e-596a-b727-8c2861db1853', (select id from categories where name = 'Çand'), 'ku-kmr', 'Li gorî efsaneya Kawayê Hesinkar, Kawa li dijî kîjan serdarê zordest serî hilda?', 'Nemrûd', 'Dehaq', 'Firewn', 'Qarûn', 'B', 'Li gorî efsaneyê Kawayê Hesinkar Dehaqê zordar têk bir û serketina xwe bi agirekî mezin da zanîn; ev agir bûye sembola Newrozê.', 'Li gorî efsaneyê Kawayê Hesinkar Dehaqê zordar têk bir û serketina xwe bi agirekî mezin da zanîn; ev agir bûye sembola Newrozê.', 'Efsaneye göre Demirci Kawa zalim Dahhak''ı devirdi ve zaferini büyük bir ateşle duyurdu; bu ateş Newroz''un simgesi oldu.', 1, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/Kaway%C3%AA_Hesinkar', 'Kawayê Hesinkar - Wîkîpediya', 'https://ku.wikipedia.org/wiki/Kaway%C3%AA_Hesinkar', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_003
('8cc40d76-e4d2-5a3e-ba49-52c5052a984f', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di destana Siyabend û Xecê de Siyabend li ser kîjan çiyayî jiyana xwe ji dest dide?', 'Sîpan', 'Agirî', 'Cûdî', 'Nemrûd', 'A', 'Siyabend li Çiyayê Sîpanê Xelatê, li bakurê Gola Wanê, ji zinaran dikeve; Xecê jî xwe li pey wî davêje û her du li heman cihî dimirin.', 'Siyabend li Çiyayê Sîpanê Xelatê, li bakurê Gola Wanê, ji zinaran dikeve; Xecê jî xwe li pey wî davêje û her du li heman cihî dimirin.', 'Siyabend, Van Gölü''nün kuzeyindeki Süphan (Sîpanê Xelatê) Dağı''nda kayalıklardan düşer; Xecê de ardından kendini atar ve ikisi aynı yerde ölür.', 2, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/Siyabend_%C3%BB_Xec%C3%AA', 'Siyabend û Xecê - Wîkîpediya', 'https://ku.wikipedia.org/wiki/Siyabend_%C3%BB_Xec%C3%AA', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_004
('6258de4b-acdf-583b-afea-1690bba3f05f', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di destana Mem û Zînê de hevalê herî nêzîk ê Mem kî ye?', 'Zeynedîn', 'Siyabend', 'Tacdîn', 'Beko', 'C', 'Tacdîn hevalê herî nêzîk ê Mem e û di destanê de tim li kêleka wî ye; piştî mirina Mem ew heyfa wî ji Beko hiltîne.', 'Tacdîn hevalê herî nêzîk ê Mem e û di destanê de tim li kêleka wî ye; piştî mirina Mem ew heyfa wî ji Beko hiltîne.', 'Tacdîn Mem''in en yakın dostudur ve destan boyunca onun yanındadır; Mem''in ölümünden sonra onun intikamını Beko''dan alır.', 2, true, 'multiple_choice', NULL, 'https://wikisource.org/wiki/Mem_%C3%BB_Z%C3%AEn_(naverok)', 'Mem û Zîn (naverok) - Wikisource', 'https://wikisource.org/wiki/Mem_%C3%BB_Z%C3%AEn_(naverok)', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_005
('aa57cd5b-9631-584d-9385-01149b9d2617', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di destana Mem û Zîna Ehmedê Xanî de Sitî çi dibe Zînê?', 'Xwişka wê', 'Keça apê wê', 'Diya wê', 'Cariya wê', 'A', 'Zîn û Sitî du xwişkên Mîrê Botan in; Sitî paşê bi Tacdîn re dizewice, lê Zîn nagihîje Mem.', 'Zîn û Sitî du xwişkên Mîrê Botan in; Sitî paşê bi Tacdîn re dizewice, lê Zîn nagihîje Mem.', 'Zîn ve Sitî, Botan Mîri''nin iki kız kardeşidir; Sitî sonradan Tacdîn''le evlenir, Zîn ise Mem''e kavuşamaz.', 2, true, 'multiple_choice', NULL, 'https://wikisource.org/wiki/Mem_%C3%BB_Z%C3%AEn_(naverok)', 'Mem û Zîn (naverok) - Wikisource', 'https://wikisource.org/wiki/Mem_%C3%BB_Z%C3%AEn_(naverok)', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_006
('6d708587-697b-525d-856d-c78aa0e3eec1', (select id from categories where name = 'Çand'), 'ku-kmr', 'Destana Zembîlfiroş a menzûm ji aliyê kîjan helbestvanê klasîk ve hatiye nivîsandin?', 'Feqiyê Teyran', 'Ehmedê Xanî', 'Melayê Cizîrî', 'Elî Herîrî', 'A', 'Zembîlfiroş mesnewiyeke Feqiyê Teyran e; ew helbestvanekî klasîk ê kurmancî ye û ev destan bi navê wî tê naskirin.', 'Zembîlfiroş mesnewiyeke Feqiyê Teyran e; ew helbestvanekî klasîk ê kurmancî ye û ev destan bi navê wî tê naskirin.', 'Zembîlfiroş, klasik Kurmancî şair Feqiyê Teyran''ın mesnevisidir; eser onun adıyla bilinir.', 2, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/Zemb%C3%AElfiro%C5%9F_(destan)', 'Zembîlfiroş (destan) - Wîkîpediya', 'https://ku.wikipedia.org/wiki/Zemb%C3%AElfiro%C5%9F_(destan)', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_007
('d2ba9287-318b-55ba-8a6d-52236fdce6b2', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di destana Siyabend û Xecê de Siyabend ji bo Xecê li pey kîjan ajalî diçe û di encamê de ji zinaran dikeve?', 'Beraz', 'Xezal', 'Hirç', 'Gur', 'B', 'Gava Xecê keriyekî xezalan dibîne, digirî; Siyabend ji bo wê li pey xezalê diçe, xezal bi qiloçên xwe lê dide û ew ji zinar dikeve.', 'Gava Xecê keriyekî xezalan dibîne, digirî; Siyabend ji bo wê li pey xezalê diçe, xezal bi qiloçên xwe lê dide û ew ji zinar dikeve.', 'Xecê bir ceylan sürüsü görünce ağlar; Siyabend onun için ceylanın peşine düşer, ceylan boynuzlarıyla ona vurur ve o kayalıktan düşer.', 2, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/Siyabend_%C3%BB_Xec%C3%AA', 'Siyabend û Xecê - Wîkîpediya', 'https://ku.wikipedia.org/wiki/Siyabend_%C3%BB_Xec%C3%AA', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_008
('fc9d86c3-2a7d-558b-b7ec-ab537394dadf', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di destana Mem û Zînê de Beko ji Mîr re dibêje ku bi Mem re kîjan lîstikê bilîze da ku sira dilê wî derxe holê?', 'Dama', 'Domîno', 'Tawle', 'Şetrenc', 'D', 'Beko hîle dike û cihê Mîr û Mem diguhere; Mem Zînê li pencereyê dibîne, bala wî diçe, lîstika şetrencê winda dike û neçar dimîne navê evîndara xwe bêje.', 'Beko hîle dike û cihê Mîr û Mem diguhere; Mem Zînê li pencereyê dibîne, bala wî diçe, lîstika şetrencê winda dike û neçar dimîne navê evîndara xwe bêje.', 'Beko hile yaparak Mîr ile Mem''in yerini değiştirtir; pencerede Zîn''i gören Mem''in dikkati dağılır, satranç oyununu kaybeder ve sevdiğinin adını söylemek zorunda kalır.', 3, true, 'multiple_choice', NULL, 'https://wikisource.org/wiki/Mem_%C3%BB_Z%C3%AEn_(naverok)', 'Mem û Zîn (naverok) - Wikisource', 'https://wikisource.org/wiki/Mem_%C3%BB_Z%C3%AEn_(naverok)', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_009
('56e82f2b-bbf8-5d05-8d5d-04a99e199224', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di destana Zembîlfiroş de Zembîlfiroş li kîjan bajarî zembîlan difiroşe?', 'Cizîr', 'Ferqîn', 'Bedlîs', 'Mêrdîn', 'B', 'Zembîlfiroş li Ferqînê (Silvana îro) zembîlan difiroşe; dilê jina mîrê bajêr dikeve wî, lê ew ji jin û zarokên xwe re dilsoz dimîne.', 'Zembîlfiroş li Ferqînê (Silvana îro) zembîlan difiroşe; dilê jina mîrê bajêr dikeve wî, lê ew ji jin û zarokên xwe re dilsoz dimîne.', 'Zembîlfiroş, Farkin''de (bugünkü Silvan) sepet satar; şehrin mîrinin karısı ona âşık olur, ama o karısına ve çocuklarına sadık kalır.', 3, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/Zemb%C3%AElfiro%C5%9F_(destan)', 'Zembîlfiroş (destan) - Wîkîpediya', 'https://ku.wikipedia.org/wiki/Zemb%C3%AElfiro%C5%9F_(destan)', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_010
('c6bec7ab-9951-5287-9330-8a24f62e902b', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di destana Mem û Zîna Xanî de Zîn û Sitî di şahiya Newrozê de bi çi cilan derdikevin nav xelkê?', 'Bi cilên derwêşan', 'Bi cilên bûkan', 'Bi cilên şivanan', 'Bi cilên xortan', 'D', 'Di Newrozê de Zîn û Sitî cilên xortan li xwe dikin, Mem û Tacdîn jî cilên keçan; ew hev dibînin, dilê wan dikeve hev û gustîlên xwe diguherin.', 'Di Newrozê de Zîn û Sitî cilên xortan li xwe dikin, Mem û Tacdîn jî cilên keçan; ew hev dibînin, dilê wan dikeve hev û gustîlên xwe diguherin.', 'Newroz''da Zîn ile Sitî erkek kıyafeti, Mem ile Tacdîn ise kız kıyafeti giyer; karşılaşıp birbirlerine gönül verirler ve yüzüklerini değiştirirler.', 4, true, 'multiple_choice', NULL, 'https://wikisource.org/wiki/Mem_%C3%BB_Z%C3%AEn_(naverok)', 'Mem û Zîn (naverok) - Wikisource', 'https://wikisource.org/wiki/Mem_%C3%BB_Z%C3%AEn_(naverok)', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_011
('eee01a23-5c0e-5903-b32c-f0e400fde1df', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di destana Mem û Zînê de, dema Zîn xwe di bin ebayê Mem de vedişêre, Tacdîn çi dike da ku Mîr ji baxçe dûr bixe?', 'Zengilê bajêr lê dide', 'Şerekî derewîn dest pê dike', 'Agir berdide qesra xwe', 'Hespên Mîr berdide', 'C', 'Tacdîn qesra xwe dişewitîne; Mîr û hevalên wî ji bo vemirandina agir diçin û Zîn bi vê firsendê ji baxçe direve.', 'Tacdîn qesra xwe dişewitîne; Mîr û hevalên wî ji bo vemirandina agir diçin û Zîn bi vê firsendê ji baxçe direve.', 'Tacdîn kendi sarayını ateşe verir; Mîr ve maiyeti yangını söndürmeye koşar ve Zîn bu fırsatla bahçeden kaçar.', 5, true, 'multiple_choice', NULL, 'https://wikisource.org/wiki/Mem_%C3%BB_Z%C3%AEn_(naverok)', 'Mem û Zîn (naverok) - Wikisource', 'https://wikisource.org/wiki/Mem_%C3%BB_Z%C3%AEn_(naverok)', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_012
('a6941b14-5c46-57f8-83e6-7359804b106e', (select id from categories where name = 'Çand'), 'ku-kmr', 'Lehengê destana Kela Dimdimê, Emîrxan, çima bi navê "Lepzêrîn" tê naskirin?', 'Ji ber şûrê wî yê zêrkirî', 'Ji ber xezîneya wî ya mezin', 'Ji ber porê wî yê zer', 'Ji ber destê wî yê ji zêr', 'D', 'Li gorî vegotinê, milê Emîrxan di şerekî de hat birîn û Şah Ebbas ji ber mêrxasiya wî milekî zêrîn jê re da çêkirin. Ji wê rojê ve jê re "Lepzêrîn" an "Çengzêrîn" tê gotin.', 'Li gorî vegotinê, milê Emîrxan di şerekî de hat birîn û Şah Ebbas ji ber mêrxasiya wî milekî zêrîn jê re da çêkirin. Ji wê rojê ve jê re "Lepzêrîn" an "Çengzêrîn" tê gotin.', 'Anlatıya göre Emîrxan''ın kolu bir savaşta kesilmiş, Şah Abbas da yiğitliği nedeniyle ona altından bir kol yaptırmıştır. O günden beri ona "Lepzêrîn" ya da "Çengzêrîn" (altın elli) denir.', 1, true, 'multiple_choice', NULL, 'https://www.bernamegeh.org/destana-kela-dimdime/', 'Destana Kela Dimdimê | Bernamegeh', 'https://www.bernamegeh.org/destana-kela-dimdime/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_013
('edff957f-fb9d-539e-9341-8b34f89fdebc', (select id from categories where name = 'Çand'), 'ku-kmr', 'Kela Dimdimê, ku lehengê destana wê Emîrxanê Lepzêrîn e, li nêzîkî kîjan golê ye?', 'Gola Dukanê', 'Gola Urmiyê', 'Gola Wanê', 'Gola Hazarê', 'B', 'Kela Dimdimê li ser Çiyayê Dimdimê ye, li rojavayê Gola Urmiyê; lewma bersiva rast Gola Urmiyê ye.', 'Kela Dimdimê li ser Çiyayê Dimdimê ye, li rojavayê Gola Urmiyê; lewma bersiva rast Gola Urmiyê ye.', 'Dimdim Kalesi, Urmiye Gölü''nün batısındaki Dimdim Dağı''ndadır; bu yüzden doğru cevap Urmiye Gölü''dür.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Dimdim_Castle', 'Dimdim Castle - Wikipedia', 'https://en.wikipedia.org/wiki/Dimdim_Castle', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_014
('d16bcd4c-4358-5028-88fb-e213f961938c', (select id from categories where name = 'Çand'), 'ku-kmr', 'Li gorî destana Kela Dimdimê, leşkerê kîjan şahî kel dorpêç kir û bi Emîrxanê Lepzêrîn re şer kir?', 'Nadir Şah', 'Şah Tehmasb', 'Şah Îsmaîl', 'Şah Ebbas', 'D', 'Kela Dimdimê artêşa Şah Ebbasê Sefewî dorpêç kir; dijminê sereke yê Emîrxanê Lepzêrîn di destanê de ew e.', 'Kela Dimdimê artêşa Şah Ebbasê Sefewî dorpêç kir; dijminê sereke yê Emîrxanê Lepzêrîn di destanê de ew e.', 'Dimdim Kalesi''ni kuşatan ordu Safevi Şah Abbas''ın ordusudur; destanda Emîrxanê Lepzêrîn''in başlıca hasmı odur.', 2, true, 'multiple_choice', NULL, 'https://www.bernamegeh.org/destana-kela-dimdime/', 'Destana Kela Dimdimê | Bernamegeh', 'https://www.bernamegeh.org/destana-kela-dimdime/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_015
('f9da51dd-0500-59f3-8e0a-998d6b0af886', (select id from categories where name = 'Çand'), 'ku-kmr', 'Kîjan nivîskarê kurd di sala 1966an de romana dîrokî ya bi navê "Dimdim" weşand, ku ji destana Kela Dimdimê îlham girtiye?', 'Mehmed Uzun', 'Hesenê Metê', 'Erebê Şemo', 'Fîrat Cewerî', 'C', 'Erebê Şemo yek ji pêşengên romana kurmancî ye; romana wî ya bi navê Dimdim ji destana Kela Dimdimê îlham girtiye.', 'Erebê Şemo yek ji pêşengên romana kurmancî ye; romana wî ya bi navê Dimdim ji destana Kela Dimdimê îlham girtiye.', 'Erebê Şemo Kurmancî romanın öncülerindendir; Dimdim adlı romanı Kela Dimdim destanından esinlenmiştir.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Arab_Shamilov', 'Arab Shamilov - Wikipedia', 'https://en.wikipedia.org/wiki/Arab_Shamilov', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_016
('fdc26754-20a7-5fba-99cf-d3e3d4a47f12', (select id from categories where name = 'Çand'), 'ku-kmr', 'Yekem vegotina wêjeyî ya şerê Dimdimê — ku destana wê piştî Mem û Zînê wekî destana duyem a neteweyî ya kurdan tê dîtin — ji aliyê kê ve hatiye nivîsandin?', 'Melayê Cizîrî', 'Ehmedê Xanî', 'Elî Herîrî', 'Feqiyê Teyran', 'D', 'Helbestvanê klasîk Feqiyê Teyran yekem car şerê Dimdimê (1609–1610) bi awayekî wêjeyî vegotiye. Di kevneşopiya devkî de ev çîrok wekî "Beyta Dimdimê" jî tê gotin.', 'Helbestvanê klasîk Feqiyê Teyran yekem car şerê Dimdimê (1609–1610) bi awayekî wêjeyî vegotiye. Di kevneşopiya devkî de ev çîrok wekî "Beyta Dimdimê" jî tê gotin.', 'Klasik şair Feqiyê Teyran, Dimdim savaşını (1609–1610) edebî olarak ilk anlatan kişidir. Sözlü gelenekte bu anlatı "Beytî Dimdim" olarak da söylenir.', 4, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/Keleha_Dimdimê', 'Keleha Dimdimê - Wîkîpediya', 'https://ku.wikipedia.org/wiki/Keleha_Dimdimê', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_017
('f1c91323-0ba1-57de-ab14-76c7ad9bc61c', (select id from categories where name = 'Çand'), 'ku-kmr', 'Cembelî, lehengê destana "Cembelî û Binevşê", kurê mîrê kîjan herêmê bû?', 'Behdînan', 'Hekarî', 'Botan', 'Soran', 'B', 'Navê tevahî yê destanê "Cembeliyê Mîrê Hekkarî û Binevşa Narîn" e; Cembelî kur û wêrisê textê Mîrê Hekariyê ye. Çîrok ji Qerejdaxê heta zozanên bilind ên Hekariyê dirêj dibe.', 'Navê tevahî yê destanê "Cembeliyê Mîrê Hekkarî û Binevşa Narîn" e; Cembelî kur û wêrisê textê Mîrê Hekariyê ye. Çîrok ji Qerejdaxê heta zozanên bilind ên Hekariyê dirêj dibe.', 'Destanın tam adı "Cembeliyê Mîrê Hekkarî û Binevşa Narîn"dir; Cembelî, Hakkari Miri''nin oğlu ve tahtının varisidir. Hikâye Karacadağ''dan Hakkari''nin yüksek yaylalarına uzanır.', 1, true, 'multiple_choice', NULL, 'https://www.colemerghaber.com/cembeliye-mire-hekkari-u-binevsa-narin-destani', 'Cembeliyê Mîrê Hekkarî û Binevşa Narîn Destanı - Hakkari Haber', 'https://www.colemerghaber.com/cembeliye-mire-hekkari-u-binevsa-narin-destani', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_018
('ff8a67a9-b9e2-50b3-aad1-ea234de07988', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di destana Cembelî û Binevşê de, leheng Cembelî ji bo ku Binevşê bibîne li ba Derwêş Beg dibe çi?', 'Nalbend', 'Aşvan', 'Bazirgan', 'Şivan', 'D', 'Derwêş Beg Binevşê direvîne û di koşkekê de girtî dihêle; Cembelî jî dev ji mîrîtiyê berdide û salan şivantiya pezê Derwêş Beg dike da ku carekê Binevşê bibîne.', 'Derwêş Beg Binevşê direvîne û di koşkekê de girtî dihêle; Cembelî jî dev ji mîrîtiyê berdide û salan şivantiya pezê Derwêş Beg dike da ku carekê Binevşê bibîne.', 'Derweş Bey Binevş''i kaçırıp bir köşke kapatır; Cembelî beylik mirasını bırakır ve Binevş''i bir kez görebilmek için yıllarca Derweş Bey''in sürülerine çobanlık eder.', 2, true, 'multiple_choice', NULL, 'https://www.colemerghaber.com/cembeliye-mire-hekkari-u-binevsa-narin-destani', 'Cembeliyê Mîrê Hekkarî û Binevşa Narîn Destanı - Hakkari Haber', 'https://www.colemerghaber.com/cembeliye-mire-hekkari-u-binevsa-narin-destani', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_019
('e1307a4a-3f8e-522d-8ad8-38d978609634', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di destana Cembelî û Binevşê de, Binevş bi dengê kîjan amûrê ku Cembelî li ber kaniyê lê dixist ji malê derdikeve?', 'Bilûr', 'Tembûr', 'Zirne', 'Erbane', 'A', 'Dengê bilûra Cembelî ewqas xweş bû ku Binevş cara yekem ji koşkê derket û ber bi wî dengî ve çû. Bilûr di destpêka çîrokê de jî heye: di hevdîtina yekem de bilûra Cembelî ketibû destê Binevşê.', 'Dengê bilûra Cembelî ewqas xweş bû ku Binevş cara yekem ji koşkê derket û ber bi wî dengî ve çû. Bilûr di destpêka çîrokê de jî heye: di hevdîtina yekem de bilûra Cembelî ketibû destê Binevşê.', 'Cembelî''nin kavalının sesi o kadar güzeldi ki Binevş ilk kez köşkten çıkıp sesin geldiği yöne gitti. Kaval hikâyenin başında da vardır: ilk karşılaşmada Cembelî''nin kavalı Binevş''in eline geçmişti.', 3, true, 'multiple_choice', NULL, 'https://www.colemerghaber.com/cembeliye-mire-hekkari-u-binevsa-narin-destani', 'Cembeliyê Mîrê Hekkarî û Binevşa Narîn Destanı - Hakkari Haber', 'https://www.colemerghaber.com/cembeliye-mire-hekkari-u-binevsa-narin-destani', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_020
('3e865fb4-3c19-54bb-92dc-932029027905', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di destana Derwêşê Evdî de, navê keça ku leheng Derwêş jê hez dike çi ye?', 'Binevş', 'Xecê', 'Zîn', 'Edûlê', 'D', 'Edûlê navê keçika ku Derwêş jê hez dike ye; evîna Derwêş û Edûlê di kilamên kurdî de tê gotin.', 'Edûlê navê keçika ku Derwêş jê hez dike ye; evîna Derwêş û Edûlê di kilamên kurdî de tê gotin.', 'Edûlê, Derwêş''in sevdiği kızın adıdır; Derwêş ile Edûlê''nin aşkı Kürt kilamlarında anlatılır.', 1, true, 'multiple_choice', NULL, 'https://candname.com/destana-dewrese-evdi-u-evina-edule/', 'Destana Dewrêşê Evdî û Evîna Edûlê – ÇandName', 'https://candname.com/destana-dewrese-evdi-u-evina-edule/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_021
('fa467b70-d334-5c31-8b33-883765394bcf', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di destana Derwêşê Evdî de, navê hespê leheng Derwêş çi bû?', 'Hedban', 'Bozê Rewan', 'Rexş', 'Şebdîz', 'A', 'Hedban navê hespê Derwêş e; di destan û kilaman de Derwêş bi Hedbanê tê bibîranîn.', 'Hedban navê hespê Derwêş e; di destan û kilaman de Derwêş bi Hedbanê tê bibîranîn.', 'Hedban, Derwêş''in atının adıdır; destan ve kilamlarda Derwêş Hedban ile birlikte anılır.', 4, true, 'multiple_choice', NULL, 'https://candname.com/destana-dewrese-evdi-u-evina-edule/', 'Destana Dewrêşê Evdî û Evîna Edûlê – ÇandName', 'https://candname.com/destana-dewrese-evdi-u-evina-edule/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_022
('c6cf2863-4ad5-55bb-8e58-1859d28e0818', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di wêjeya devkî ya kurdî de, navê hespê lehengê navdar Ristemê Zal çi ye?', 'Şebdîz', 'Bor', 'Rexş', 'Hedban', 'C', 'Ristemê Zal lehengekî destan û çanda devkî ya kurdan e û hespê wî Rexş e. Çîrokên wî di Şahnameya Firdewsî de jî cih digirin.', 'Ristemê Zal lehengekî destan û çanda devkî ya kurdan e û hespê wî Rexş e. Çîrokên wî di Şahnameya Firdewsî de jî cih digirin.', 'Zaloğlu Rüstem, Kürt destan ve sözlü kültürünün kahramanlarındandır; atının adı Rahş''tır. Hikâyeleri Firdevsî''nin Şehname''sinde de yer alır.', 2, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/Rûstemê_Zal', 'Ristemê Zal - Wîkîpediya', 'https://ku.wikipedia.org/wiki/Rûstemê_Zal', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_023
('6743db8d-65fc-5224-b999-0f75b69a3a12', (select id from categories where name = 'Çand'), 'ku-kmr', 'Helbestvanê kurd Xana Qubadî destana evînê ya "Şîrîn û Xusrew" di sala 1740an de bi kîjan zaravayê kurdî nivîsiye?', 'Hewramî', 'Kurmancî', 'Soranî', 'Zazakî', 'A', 'Xana Qubadî helbestvanê kevneşopiya Gûranî-Hewramî ye; berhema wî ya Şîrîn û Xusrew bi hewramî hatiye nivîsîn.', 'Xana Qubadî helbestvanê kevneşopiya Gûranî-Hewramî ye; berhema wî ya Şîrîn û Xusrew bi hewramî hatiye nivîsîn.', 'Xana Qubadî Gorani-Hewrami geleneğinin şairidir; Şîrîn ile Hüsrev eserini Hewramice yazmıştır.', 5, true, 'multiple_choice', NULL, 'https://ku.wikipedia.org/wiki/Xana_Qubadî', 'Xana Qubadî - Wîkîpediya', 'https://ku.wikipedia.org/wiki/Xana_Qubadî', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_dastangotin_024
('004fbb44-5c21-570b-abec-9b160e37449d', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di mamik û tiştonekên kurdî de bersiva "Goma bavê min tije pez e, şefeqê radibim hebek tune ye" çi ye?', 'Roj', 'Stêrk', 'Birûsk', 'Hîv', 'B', 'Di vê mamikê de ezmanê şevê wek gomeke tije pez hatiye wesifandin: stêrk bi şev bêhejmar xuya dikin, lê bi şefeqê re yek jî namîne.', 'Di vê mamikê de ezmanê şevê wek gomeke tije pez hatiye wesifandin: stêrk bi şev bêhejmar xuya dikin, lê bi şefeqê re yek jî namîne.', 'Bu bilmecede gece göğü koyunla dolu bir ağıla benzetilir: yıldızlar gece sayısızca görünür, şafak sökünce hiçbiri kalmaz.', 2, true, 'multiple_choice', NULL, 'https://occomahabad.wordpress.com/2012/08/20/mamiken-kurdi-kurtce-bilmeceler/', 'Mamikên Kurdî-Kürtçe bilmeceler…. | occo mahabad', 'https://occomahabad.wordpress.com/2012/08/20/mamiken-kurdi-kurtce-bilmeceler/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_001
('f700963f-7f9c-5803-85d7-db590f1f3a25', (select id from categories where name = 'Çand'), 'ku-kmr', 'Bersiva vê tiştonekê, ku jê re mamik jî tê gotin, çi ye: "Şev têt, şemal têt; gah têt, gopal têt; nik padîşah û sultan têt"?', 'Hîv', 'Birûsk', 'Stêrk', 'Roj', 'A', 'Hîv bi şev wek şemalekê ronahiyê dide; dema ku hilal e, dişibe gopalekê. Ew li ser her kesî, ji padîşah heta gundiyan, dibiriqe.', 'Hîv bi şev wek şemalekê ronahiyê dide; dema ku hilal e, dişibe gopalekê. Ew li ser her kesî, ji padîşah heta gundiyan, dibiriqe.', 'Ay gece bir kandil gibi ışık verir; hilal hâlindeyken bir değneğe benzer. Padişahtan köylüye herkesin üzerine ışığını düşürür.', 2, true, 'multiple_choice', NULL, 'https://candname.com/di-mamikan-de-dacek/', 'Di mamikan de Daçek – ÇandName (Kenan Subaşi)', 'https://candname.com/di-mamikan-de-dacek/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_002
('d417d63b-287b-5e4a-a7e8-93c179ba1eb7', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di mamik û tiştonekên kurdî de bersiva "Xalkî xala, çû pişt mala, şingîn kete ezmana" çi ye?', 'Berf', 'Birûsk', 'Baran', 'Mij', 'B', 'Birûsk ji nişkê ve li pişt xaniyan dibiriqe û deng li ezmên belav dibe; mamik vê yekê bi peyva "şingîn" nîşan dide.', 'Birûsk ji nişkê ve li pişt xaniyan dibiriqe û deng li ezmên belav dibe; mamik vê yekê bi peyva "şingîn" nîşan dide.', 'Şimşek birden evlerin ardında çakar ve sesi göğe yayılır; bilmece bunu "şingîn" (çınlama) sözüyle anlatır.', 5, true, 'multiple_choice', NULL, 'https://candname.com/di-mamikan-de-dacek/', 'Di mamikan de Daçek – ÇandName (Kenan Subaşi)', 'https://candname.com/di-mamikan-de-dacek/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_003
('e32c38f9-4148-5179-b3ba-bea7ef74a544', (select id from categories where name = 'Çand'), 'ku-kmr', 'Mamikeke kurdî (tiştonek) wiha dibêje: "Ji hire heta Mûsil hemî morîyên sinsil." Bersiv çi ye?', 'Berf', 'Ba', 'Birûsk', 'Baran', 'D', 'Dilopên baranê ji ezmên wek rêzên moriyan dadikevin û welatekî fireh digirin; loma mamik baranê dişibîne moriyên li hev rêzkirî.', 'Dilopên baranê ji ezmên wek rêzên moriyan dadikevin û welatekî fireh digirin; loma mamik baranê dişibîne moriyên li hev rêzkirî.', 'Yağmur damlaları gökten dizi dizi boncuklar gibi iner ve geniş bir ülkeyi kaplar; bilmece bu yüzden yağmuru dizilmiş boncuklara benzetir.', 3, true, 'multiple_choice', NULL, 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'Pêvek:Mamik - Wîkîferheng (Mirad Gundikî, Mamikê min ê mamanî)', 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_004
('e895b311-9e6b-5908-a769-f5b2e79b7cbe', (select id from categories where name = 'Çand'), 'ku-kmr', 'Bersiva vê tiştonekê, ku jê re mamik jî tê gotin, çi ye: "Ji hire heta Bexda kulav rada"?', 'Baran', 'Berf', 'Ba', 'Birûsk', 'B', 'Berf erdê ji vir heta dûr wek kulavekî spî dinixumîne; kulav raxistineke kevneşopî ya malên kurdan e.', 'Berf erdê ji vir heta dûr wek kulavekî spî dinixumîne; kulav raxistineke kevneşopî ya malên kurdan e.', 'Kar, toprağı buradan uzaklara kadar beyaz bir keçe gibi örter; keçe (kulav) Kürt evlerinin geleneksel yaygısıdır.', 2, true, 'multiple_choice', NULL, 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'Pêvek:Mamik - Wîkîferheng (Mirad Gundikî, Mamikê min ê mamanî)', 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_005
('3b68d9e2-bf07-5eb1-906c-b607257519fb', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di mamik û tiştonekên kurdî de bersiva "Hanyan e, manyan e, ferşê derê kaniyan e, rê nade karwaniyan e" çi ye?', 'Qeşa', 'Ba', 'Mij', 'Baran', 'A', 'Di zivistanê de ava ber kaniyan dicemide û wek ferşekê li ser erdê raxistî dimîne; qeşa ew qas şemitok e ku karwan nikarin bi hêsanî di ser re derbas bibin.', 'Di zivistanê de ava ber kaniyan dicemide û wek ferşekê li ser erdê raxistî dimîne; qeşa ew qas şemitok e ku karwan nikarin bi hêsanî di ser re derbas bibin.', 'Kışın pınar önlerindeki su donar ve yere halı gibi serilir; buz o kadar kaygandır ki kervanlar üzerinden kolayca geçemez.', 4, true, 'multiple_choice', NULL, 'https://occomahabad.wordpress.com/2012/08/20/mamiken-kurdi-kurtce-bilmeceler/', 'Mamikên Kurdî-Kürtçe bilmeceler…. | occo mahabad', 'https://occomahabad.wordpress.com/2012/08/20/mamiken-kurdi-kurtce-bilmeceler/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_006
('6dcace82-020f-5e9a-9734-19e6e0862285', (select id from categories where name = 'Çand'), 'ku-kmr', 'Mamikeke kurdî (tiştonek) wiha dibêje: "Kalokî tê ji deştê, barê striyan li piştê." Bersiv çi ye?', 'Kêvroşk', 'Jîjo', 'Rovî', 'Kûsî', 'B', 'Jîjo ajalekî biçûk e ku pişta wî bi striyan nixumandî ye; loma mamik wî dişibîne kalekî ku barê striyan li pişta xwe kiriye.', 'Jîjo ajalekî biçûk e ku pişta wî bi striyan nixumandî ye; loma mamik wî dişibîne kalekî ku barê striyan li pişta xwe kiriye.', 'Kirpi sırtı dikenlerle kaplı küçük bir hayvandır; bilmece onu sırtına diken yükü almış bir ihtiyara benzetir.', 1, true, 'multiple_choice', NULL, 'https://occomahabad.wordpress.com/2012/08/20/mamiken-kurdi-kurtce-bilmeceler/', 'Mamikên Kurdî-Kürtçe bilmeceler…. | occo mahabad', 'https://occomahabad.wordpress.com/2012/08/20/mamiken-kurdi-kurtce-bilmeceler/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_007
('cfdaadbe-3939-5159-804c-d5c61cc3d1eb', (select id from categories where name = 'Çand'), 'ku-kmr', 'Bersiva vê tiştonekê, ku jê re mamik jî tê gotin, çi ye: "Ser text e, bin text e, di navê de pîrek bêbext e"?', 'Mişk', 'Beq', 'Jîjo', 'Kûsî', 'D', 'Kûsî di nav qalikekî hişk de dijî ku hem pişt û hem jî binê laşê wê diparêze; mamik vî qalikî dişibîne du textan.', 'Kûsî di nav qalikekî hişk de dijî ku hem pişt û hem jî binê laşê wê diparêze; mamik vî qalikî dişibîne du textan.', 'Kaplumbağa hem sırtını hem karnını koruyan sert bir kabuğun içinde yaşar; bilmece bu kabuğu iki tahtaya benzetir.', 1, true, 'multiple_choice', NULL, 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'Pêvek:Mamik - Wîkîferheng (Mirad Gundikî, Mamikê min ê mamanî)', 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_008
('d405c2d7-dc39-5bbc-8146-f0dbe7562051', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di mamik û tiştonekên kurdî de bersiva "Dirêj e, ne bend e, gez dike ne kûçik e" çi ye?', 'Kêç', 'Mar', 'Mişk', 'Dûpişk', 'B', 'Mar ajalekî dirêj û bê ling e ku dişibe bendekî; hin celebên wî bi gezandinê jehrê berdidin laşê mirov.', 'Mar ajalekî dirêj û bê ling e ku dişibe bendekî; hin celebên wî bi gezandinê jehrê berdidin laşê mirov.', 'Yılan ipe benzeyen uzun ve bacaksız bir hayvandır; bazı türleri ısırarak zehir akıtır.', 1, true, 'multiple_choice', NULL, 'https://candname.com/tistanok/', 'Tiştanok-1 – ÇandName (Paşa Amedî)', 'https://candname.com/tistanok/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_009
('be9b3d6f-c509-5837-b2ef-9b91509a476d', (select id from categories where name = 'Çand'), 'ku-kmr', 'Mamikeke kurdî (tiştonek) wiha dibêje: "Hûr e wekî kirzin, reş e weku bizin, hakim ji ber dilerizin." Bersiv çi ye?', 'Moz', 'Mişk', 'Kêç', 'Pinpinîk', 'C', 'Kêç kêzikeke gelekî biçûk û reş e ku xwîna mirov û ajalan dimije; gezandina wê her kesî, hakiman jî, bêrehet dike.', 'Kêç kêzikeke gelekî biçûk û reş e ku xwîna mirov û ajalan dimije; gezandina wê her kesî, hakiman jî, bêrehet dike.', 'Pire, insan ve hayvan kanı emen çok küçük ve koyu renkli bir böcektir; ısırığı hâkimler dahil herkesi rahatsız eder.', 3, true, 'multiple_choice', NULL, 'https://candname.com/di-mamikan-de-dacek/', 'Di mamikan de Daçek – ÇandName (Kenan Subaşi)', 'https://candname.com/di-mamikan-de-dacek/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_010
('d33b867a-64ed-5359-9a62-f9bd3232e152', (select id from categories where name = 'Çand'), 'ku-kmr', 'Bersiva vê tiştonekê, ku jê re mamik jî tê gotin, çi ye: "Bi şev bi roj mezin dibe, damarê wî heye, xwîna wî tune ye"?', 'Ewr', 'Dar', 'Kevir', 'Çem', 'B', 'Dar her dem mezin dibin û di qurm û pelên wan de damar hene ku avê digihînin şaxan, lê xwîna wan tune.', 'Dar her dem mezin dibin û di qurm û pelên wan de damar hene ku avê digihînin şaxan, lê xwîna wan tune.', 'Ağaçlar sürekli büyür; gövde ve yapraklarındaki damarlar suyu dallara taşır, ama kanları yoktur.', 2, true, 'multiple_choice', NULL, 'https://candname.com/di-mamikan-de-dacek/', 'Di mamikan de Daçek – ÇandName (Kenan Subaşi)', 'https://candname.com/di-mamikan-de-dacek/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_011
('78db12ef-ed64-504e-9a0a-c001c60c0ef3', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di mamik û tiştonekên kurdî de bersiva "Sîniya savarê ya li ser guhê darê" çi ye?', 'Behîv', 'Sêv', 'Hinar', 'Hirmî', 'C', 'Hinar li ser darê digihîje û hundirê wê tije libên biçûk e ku dişibin savarê; loma ew wek sîniyeke savarê tê wesifandin.', 'Hinar li ser darê digihîje û hundirê wê tije libên biçûk e ku dişibin savarê; loma ew wek sîniyeke savarê tê wesifandin.', 'Nar ağaçta olgunlaşır ve içi bulgura benzeyen küçük tanelerle doludur; bu yüzden bir bulgur tepsisine benzetilir.', 3, true, 'multiple_choice', NULL, 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'Pêvek:Mamik - Wîkîferheng (Mirad Gundikî, Mamikê min ê mamanî)', 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_012
('21393dfa-5730-51d0-8fee-9e7ca6633567', (select id from categories where name = 'Çand'), 'ku-kmr', 'Mamikeke kurdî (tiştonek) wiha dibêje: "Tiştekî min heye, sindoqa xilqandî, li ser darê daliqandî." Bersiv çi ye?', 'Gûz', 'Tirî', 'Sêv', 'Hirmî', 'A', 'Gûz di nav qalikekî hişk de ye ku wek sindoqeke girtî ye; ew heta ku digihîje li ser darê daliqandî dimîne.', 'Gûz di nav qalikekî hişk de ye ku wek sindoqeke girtî ye; ew heta ku digihîje li ser darê daliqandî dimîne.', 'Ceviz, kapalı bir sandık gibi sert bir kabuğun içindedir; olgunlaşana kadar ağaçta asılı kalır.', 2, true, 'multiple_choice', NULL, 'https://candname.com/di-mamikan-de-dacek/', 'Di mamikan de Daçek – ÇandName (Kenan Subaşi)', 'https://candname.com/di-mamikan-de-dacek/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_013
('4ad2eb3a-3995-5f52-805c-a6d1dd6f5878', (select id from categories where name = 'Çand'), 'ku-kmr', 'Mamikeke kurdî (tiştonek) dipirse: "Minareya sor e di bin erdê de çi ye?" Bersiv kîjan e?', 'Sîr', 'Pîvaz', 'Gêzer', 'Kartol', 'C', 'Gêzer (gêzir) kokeke dirêj û sor e ku di bin axê de mezin dibe; teşeya wê ya dirêj û tûj dişibe minareyekê.', 'Gêzer (gêzir) kokeke dirêj û sor e ku di bin axê de mezin dibe; teşeya wê ya dirêj û tûj dişibe minareyekê.', 'Havuç, toprağın altında büyüyen uzun ve kırmızımsı bir köktür; uzun ve sivri biçimi bir minareyi andırır.', 1, true, 'multiple_choice', NULL, 'https://candname.com/di-mamikan-de-dacek/', 'Di mamikan de Daçek – ÇandName (Kenan Subaşi)', 'https://candname.com/di-mamikan-de-dacek/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_014
('b4f5db46-aa82-5cbd-9d07-fd3aa0db7779', (select id from categories where name = 'Çand'), 'ku-kmr', 'Bersiva vê tiştonekê (mamikê) çi ye? "Qesra spî bê derî"', 'Sêv', 'Hêk', 'Gûz', 'Hinar', 'B', 'Qalikê hêkê spî ye û tu derî lê tune ye, loma jê re "qesra spî bê derî" tê gotin. Ev mamik hem di berhevoka Gundikê Melî de hem jî di mamikên Botanê de derbas dibe.', 'Qalikê hêkê spî ye û tu derî lê tune ye, loma jê re "qesra spî bê derî" tê gotin. Ev mamik hem di berhevoka Gundikê Melî de hem jî di mamikên Botanê de derbas dibe.', 'Yumurtanın kabuğu beyazdır ve hiçbir kapısı yoktur; bu yüzden ona "kapısız beyaz saray" denir. Bu bilmece hem Gundikê Melî derlemesinde hem de Botan bilmecelerinde geçer.', 1, true, 'multiple_choice', NULL, 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'Pêvek:Mamik – Wîkîferheng (Mirad Gundikî, "Mamikê min ê mamanî")', 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_015
('89908682-0e97-5c8a-a4ea-dc45436c2103', (select id from categories where name = 'Çand'), 'ku-kmr', 'Ev mamik li ser çi ye? "Gayê vilo, heft cilo" — bersiva tiştonekê bibêje.', 'Hêk', 'Gûz', 'Pîvaz', 'Kundir', 'C', 'Pîvaz ji gelek qatên li ser hev pêk tê; mamik van qatan dişibîne heft "cilên" ku li ser pişta gayekî ne.', 'Pîvaz ji gelek qatên li ser hev pêk tê; mamik van qatan dişibîne heft "cilên" ku li ser pişta gayekî ne.', 'Soğan üst üste binmiş pek çok katmandan oluşur; bilmece bu katmanları bir öküzün sırtındaki yedi "çula" benzetir.', 1, true, 'multiple_choice', NULL, 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'Mamikên Kurdî – Bernamegeh (15 Haziran 2019)', 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_016
('5a67dba2-4623-514c-ae4d-b8476443ade1', (select id from categories where name = 'Çand'), 'ku-kmr', 'Bersiva vê mamikê çi ye? "Wek stêrkan diçirûske, rondik davê wek nîsk e, li ser dileqe birû û bisk e" (tiştonek)', 'Çav', 'Poz', 'Dev', 'Guh', 'A', 'Çav wek stêrkan dibiriqe, rondik jê diherikin û birû li ser wî ne. Ev mamik ji rêzeke mamikên li ser endamên laş e ku Fergîn Melîk Aykoç amade kiriye.', 'Çav wek stêrkan dibiriqe, rondik jê diherikin û birû li ser wî ne. Ev mamik ji rêzeke mamikên li ser endamên laş e ku Fergîn Melîk Aykoç amade kiriye.', 'Göz yıldız gibi parlar, ondan gözyaşı akar ve kaşlar onun üstündedir. Bu bilmece, Fergîn Melîk Aykoç''un derlediği vücut organlarıyla ilgili bir dizinin parçasıdır.', 1, true, 'multiple_choice', NULL, 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'Mamikên Kurdî – Bernamegeh (15 Haziran 2019)', 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_017
('e4a36303-19c2-535d-a902-c2e890d8acbf', (select id from categories where name = 'Çand'), 'ku-kmr', 'Ev tiştonek behsa çi dike? "Cêwî ne, li kêlek in, ne goşt in lê nermik in, dengan kom dikin" — bersiva mamikê çi ye?', 'Poz', 'Çav', 'Guh', 'Lêv', 'C', 'Du guhên mirov wek cêwiyan li her du aliyên serî ne û deng berhev dikin. Mamik bi vê yekê taybetiya bihîstinê nîşan dide.', 'Du guhên mirov wek cêwiyan li her du aliyên serî ne û deng berhev dikin. Mamik bi vê yekê taybetiya bihîstinê nîşan dide.', 'İnsanın iki kulağı başın iki yanında ikizler gibi durur ve sesleri toplar. Bilmece bu yönüyle işitme özelliğini anlatır.', 1, true, 'multiple_choice', NULL, 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'Mamikên Kurdî – Bernamegeh (15 Haziran 2019)', 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_018
('64962dd9-e2d3-5211-80af-cfdbb2e46e9a', (select id from categories where name = 'Çand'), 'ku-kmr', 'Bersiva vê mamikê (tiştonekê) çi ye? "Mezela şuştî û miştî, du feqên çavreş tê de rûniştî"', 'Tirî', 'Gûz', 'Hinar', 'Sêv', 'B', 'Qalikê gûzê odeyeke girtî ye û du nîvên nav wê wek du feqeyên ku li hundir rûniştine xuya dikin. Li Bernamegehê guhertoyeke wê jî heye: "Qesra maliştî, du feqe têda rûniştî".', 'Qalikê gûzê odeyeke girtî ye û du nîvên nav wê wek du feqeyên ku li hundir rûniştine xuya dikin. Li Bernamegehê guhertoyeke wê jî heye: "Qesra maliştî, du feqe têda rûniştî".', 'Cevizin kabuğu kapalı bir odadır, içindeki iki yarım da içeride oturan iki talebeye benzer. Bernamegeh''te bir başka biçimi de geçer: "Qesra maliştî, du feqe têda rûniştî".', 2, true, 'multiple_choice', NULL, 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'Pêvek:Mamik – Wîkîferheng (Mirad Gundikî, "Mamikê min ê mamanî")', 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_019
('a337c310-b3af-5127-a220-bcb1fc4ccd6a', (select id from categories where name = 'Çand'), 'ku-kmr', 'Ev tiştonek çi ye? "Şil bike, rep bike, tê re bike" — bersiva mamikê bibêje.', 'Kilît û derî', 'Qelem û kaxiz', 'Ta û derzî', 'Kevçî û beroş', 'C', 'Berî ku ta di qula derziyê re derbas bibe, serê wê şil dikin da ku rep bibe. Heman mamik li Bernamegehê wek "Şil dikim, rep dikim, têda dikim" hatiye nivîsîn.', 'Berî ku ta di qula derziyê re derbas bibe, serê wê şil dikin da ku rep bibe. Heman mamik li Bernamegehê wek "Şil dikim, rep dikim, têda dikim" hatiye nivîsîn.', 'İplik iğnenin deliğinden geçirilmeden önce ucu ıslatılır ki dikleşsin. Aynı bilmece Bernamegeh''te "Şil dikim, rep dikim, têda dikim" biçiminde geçer.', 2, true, 'multiple_choice', NULL, 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'Pêvek:Mamik – Wîkîferheng (Mirad Gundikî, "Mamikê min ê mamanî")', 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_020
('5e5eea21-04c7-5e3a-a265-e04e62aee917', (select id from categories where name = 'Çand'), 'ku-kmr', 'Bersiva vê mamikê çi ye? "Şikefta tarî, tijî tê de mirarî" (tiştonek)', 'Por û kezî', 'Dest û tilî', 'Çav û bijang', 'Dev û didan', 'D', 'Dev şikefteke tarî ye û didanên spî di nav de wek mirariyan (moriyan) rêzkirî ne. Bernamegeh jî "Şikeftek tarî, tê de tijî mirarî" bi bersiva "dev" dide.', 'Dev şikefteke tarî ye û didanên spî di nav de wek mirariyan (moriyan) rêzkirî ne. Bernamegeh jî "Şikeftek tarî, tê de tijî mirarî" bi bersiva "dev" dide.', 'Ağız karanlık bir mağaradır, içindeki beyaz dişler de inciler gibi dizilidir. Bernamegeh de "Şikeftek tarî, têde tijî mirarî" bilmecesini "ağız" cevabıyla verir.', 2, true, 'multiple_choice', NULL, 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'Pêvek:Mamik – Wîkîferheng (Mirad Gundikî, "Mamikê min ê mamanî")', 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_021
('9fb7daf1-4c8f-590d-a145-24afb2ae36f6', (select id from categories where name = 'Çand'), 'ku-kmr', 'Ev mamik li ser kîjan endamê laş e? "Şil e ziwa nabe, bê xwê ye genî nabe" — bersiva tiştonekê çi ye?', 'Tilî', 'Ziman', 'Por', 'Guh', 'B', 'Ziman her dem di devê şil de ye û qet ziwa nabe; tevî ku xwê lê nayê kirin jî xera nabe. Ev mamik di berhevoka Serdar Can a li Bernamegehê de ye.', 'Ziman her dem di devê şil de ye û qet ziwa nabe; tevî ku xwê lê nayê kirin jî xera nabe. Ev mamik di berhevoka Serdar Can a li Bernamegehê de ye.', 'Dil her zaman ıslak ağızda durur ve hiç kurumaz; tuzlanmadığı hâlde bozulmaz. Bu bilmece Bernamegeh''teki Serdar Can derlemesinde yer alır.', 2, true, 'multiple_choice', NULL, 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'Mamikên Kurdî – Bernamegeh (15 Haziran 2019)', 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_022
('9e490e37-c8e0-563d-aafb-fad10c984467', (select id from categories where name = 'Çand'), 'ku-kmr', 'Bersiva vê tiştonekê (mamikê) çi ye? "Vî milî text e, wî milî text e, navê de şil û şeht e"', 'Penêr', 'Mast', 'Doşav', 'Hevîr', 'D', 'Hevîrê nerm û şil di navbera du textan de, wek textê hevîrkirinê, tê danîn. Ev mamik hem di berhevoka Gundikê Melî de hem jî di "Mamikên Botan" de bi heman bersivê heye.', 'Hevîrê nerm û şil di navbera du textan de, wek textê hevîrkirinê, tê danîn. Ev mamik hem di berhevoka Gundikê Melî de hem jî di "Mamikên Botan" de bi heman bersivê heye.', 'Yumuşak ve ıslak hamur, hamur tahtası gibi iki tahta arasında durur. Bu bilmece hem Gundikê Melî derlemesinde hem de "Mamikên Botan"da aynı cevapla geçer.', 3, true, 'multiple_choice', NULL, 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'Pêvek:Mamik – Wîkîferheng (Mirad Gundikî, "Mamikê min ê mamanî")', 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_023
('1a83ec61-93b7-5f1a-9092-6a1a90d8f495', (select id from categories where name = 'Çand'), 'ku-kmr', 'Ev tiştonek behsa kîjan cilî dike? "Ez di devekî re diçim, di sisiyan re derdikevim" — bersiva mamikê çi ye?', 'Pêlav', 'Gore', 'Kiras', 'Kum', 'C', 'Mirov kiras ji devekî (ji jêr ve) li xwe dike, lê serî ji stûyê wî û her du dest ji her du milên wî derdikevin, yanî ji sê devan.', 'Mirov kiras ji devekî (ji jêr ve) li xwe dike, lê serî ji stûyê wî û her du dest ji her du milên wî derdikevin, yanî ji sê devan.', 'Gömlek tek bir ağızdan (alttan) giyilir, ama baş ve iki kol üç ağızdan çıkar: yakadan ve iki kol ağzından.', 3, true, 'multiple_choice', NULL, 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'Mamikên Kurdî – Bernamegeh (15 Haziran 2019)', 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_024
('047cb9c5-2ffc-5829-93ac-3249d4c39ec5', (select id from categories where name = 'Çand'), 'ku-kmr', 'Li hin herêman ji tiştonekê re navekî din tê gotin û pirs bi qalibekî taybet dest pê dike. Ew qalib kîjan e?', 'Carekê ji caran hebû', 'Guh bidin gotina min', 'Hebû tunebû, li welatekî', 'Mamikê min ê mamanî', 'D', 'Li gor Wîkîferhengê, yên ku jê re dibêjin mamik bi "Mamikê min ê mamanî… çi ye?" dipirsin; yên ku jê re dibêjin tiştonek jî bi "Tişteka min heye… çi ye?" dest pê dikin.', 'Li gor Wîkîferhengê, yên ku jê re dibêjin mamik bi "Mamikê min ê mamanî… çi ye?" dipirsin; yên ku jê re dibêjin tiştonek jî bi "Tişteka min heye… çi ye?" dest pê dikin.', 'Vikisözlük''e göre ona mamik diyenler "Mamikê min ê mamanî… çi ye?" diye sorar; tiştonek diyenler ise "Tişteka min heye… çi ye?" diye başlar.', 2, true, 'multiple_choice', NULL, 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'Pêvek:Mamik – Wîkîferheng (Mirad Gundikî, "Mamikê min ê mamanî")', 'https://ku.wiktionary.org/wiki/P%C3%AAvek:Mamik', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_025
('29a93f1c-505b-5693-8229-2c2145a27f8c', (select id from categories where name = 'Çand'), 'ku-kmr', 'Bersiva vê mamikê çi ye? "Darek e, li ser darê hinarek e, li ser hinarê gopalek e, li ser gopalê rist e, li ser ristê bihust e" (tiştonek)', 'Mêzîn', 'Teşî', 'Sivnik', 'Bêjing', 'B', 'Teşî amûra rêsandina hiriyê ye: darikek e ku girikekî girover (wek hinarekê) pê ve ye, û rista ku tê rêsandin li dora wê tê pêçan.', 'Teşî amûra rêsandina hiriyê ye: darikek e ku girikekî girover (wek hinarekê) pê ve ye, û rista ku tê rêsandin li dora wê tê pêçan.', 'Kirmen (teşî) yün eğirme aletidir: nar gibi yuvarlak bir ağırlık takılı bir çubuktur ve eğrilen ip onun etrafına sarılır.', 4, true, 'multiple_choice', NULL, 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'Mamikên Kurdî – Bernamegeh (15 Haziran 2019)', 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_026
('98543e5c-56b5-54e4-bbc5-74c3baba4913', (select id from categories where name = 'Çand'), 'ku-kmr', 'Ev tiştonek behsa çi dike? "Av e, ne av e, nanê mirî di nav e, teyrê zêrîn hindav e" — bersiva mamikê çi ye?', 'Cêr', 'Beroş', 'Tenûr', 'Lambe', 'D', 'Di lambeya kevn de rûn heye ku wek avê ye lê ne av e, fitîl di nav de ye û agirê zer li jor wek "teyrekî zêrîn" dişewite.', 'Di lambeya kevn de rûn heye ku wek avê ye lê ne av e, fitîl di nav de ye û agirê zer li jor wek "teyrekî zêrîn" dişewite.', 'Eski lambada su gibi görünen ama su olmayan yağ ve onun içinde bir fitil vardır; üstte yanan sarı alev de "altın bir kuş" gibidir.', 4, true, 'multiple_choice', NULL, 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'Mamikên Kurdî – Bernamegeh (15 Haziran 2019)', 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_027
('905f6919-11a5-5ea9-b0be-5f745d8aaadf', (select id from categories where name = 'Çand'), 'ku-kmr', 'Bersiva vê tiştonekê (mamikê) çi ye? "Tenûr axîn, dûkêşk darîn, bobhêrk çermîn"', 'Beroş', 'Bilûr', 'Qelûn', 'Lambe', 'C', 'Serê qelûnê yê axîn wek tenûreke biçûk e ku titûn tê de dişewite, qamîşa wê ya darîn jî dû dikişîne. Ev mamik di berhevoka Bernamegehê de bi bersiva "qelûn" hatiye dayîn.', 'Serê qelûnê yê axîn wek tenûreke biçûk e ku titûn tê de dişewite, qamîşa wê ya darîn jî dû dikişîne. Ev mamik di berhevoka Bernamegehê de bi bersiva "qelûn" hatiye dayîn.', 'Piponun (qelûn) topraktan başı, tütünün yandığı küçük bir tandır gibidir; tahta sapı da dumanı çeker. Bu bilmece Bernamegeh derlemesinde "qelûn" cevabıyla verilir.', 5, true, 'multiple_choice', NULL, 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'Mamikên Kurdî – Bernamegeh (15 Haziran 2019)', 'https://www.bernamegeh.org/mamiken-kurdi-kurtce-bilmeceler/', 'approved', 'Kurmancî', 2, now()), -- yerel: ex28_tistonek_028
('99454cc4-6ebf-53db-badd-c53ea08dec57', (select id from categories where name = 'Çand'), 'ku-kmr', '"Xelat" çi ye?', 'Diyarî an pêşkêş', 'Dapîr', 'Cejn an şahî', 'Bav û kal', 'A', '"Xelat" tê wateya diyarî an pêşkêşê.', '"Xelat" tê wateya diyarî an pêşkêşê.', '"xelat" hediye ya da ödül anlamına gelir.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2066
('eedaca71-84cc-5336-bf8b-23aac654c7eb', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di çanda Kurdî de zêmar bi giştî xwedî kîjan fonksiyonê ne?', 'mêvanperwerî û daxwaza avakirina têkiliyê', 'bihar, nûbûn û azadî/berxwedan', 'veguhastina êş, windahî û bîra civakî', 'Îranî û gelek gelên din (wek Newrozê)', 'C', 'Şînî ne tenê şîna kesane, bîra bûyerên civakî û êşa hevbeş jî hildigire.', 'Şînî ne tenê şîna kesane, bîra bûyerên civakî û êşa hevbeş jî hildigire.', 'Ağıtlar, bireysel yasın yanında toplumsal olayların ve kolektif acının hafızasını taşır.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2261
('b0dd35fe-26b1-5a70-b3f4-620121c1fb45', (select id from categories where name = 'Çand'), 'ku-kmr', 'Li ser sifreyên kurdî parvekirina xwarinê bi sêniya mezin an pêşkêşiya hevpar çi xurt dike?', 'girêdanên civak û malbatê', 'pergala îmtîhana bêdeng', 'tenêtiya kesane', 'qedexeya xwarinê', 'A', 'Pêşkêşkirin û parvekirina hevbeş pratîkên çandî ne ku têkiliyên malbat, cîranî û mêvanperweriyê xurt dikin.', 'Pêşkêşkirin û parvekirina hevbeş pratîkên çandî ne ku têkiliyên malbat, cîranî û mêvanperweriyê xurt dikin.', 'Ortak sunum ve paylaşım, aile, komşuluk ve misafirlik ilişkilerini güçlendiren kültürel pratiklerdir.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2270
('fcb965f9-eb86-5f64-b593-f492adf19ffe', (select id from categories where name = 'Çand'), 'ku-kmr', 'Vexwarina ji cureyê Dew/doogh bi kîjan madeya sereke re têkildar e?', 'lîkora qehweyê', 'tenê qalikê lîmonê', 'mast/dew', 'arê garisê', 'C', 'Dew vexwarineke hênikker e ku ji mast tê çêkirin û bi kevneşopiyê ve girêdayî ye.', 'Dew vexwarineke hênikker e ku ji mast tê çêkirin û bi kevneşopiyê ve girêdayî ye.', 'Dew/doogh, yoğurt temelli ferahlatıcı bir içecek geleneğiyle ilişkilidir.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2271
('5701a6c0-be34-578b-8500-a6b25da7eed0', (select id from categories where name = 'Çand'), 'ku-kmr', 'Êzidî di erdnîgariya çandî ya kurdî de bi taybetî bi kîjan sernavî têne bibîranîn?', 'veguhastina êş, windahî û bîra civakî', 'Îranî û gelek gelên din (wek Newrozê)', 'tora rêxistinbûna civakî, ewlehî, hilberîn û têkiliya siyasî', 'civaka olî-çandî ya taybet û trawmayên dîrokî', 'D', 'Êzidî di nav civakên kurdîaxêv de bi baweriya xwe ya taybet û trawmayên dawî tên naskirin.', 'Êzidî di nav civakên kurdîaxêv de bi baweriya xwe ya taybet û trawmayên dawî tên naskirin.', 'Ezidiler, Kürtçe konuşan/kimliklenen topluluklar arasında özgün inanç yapıları ve yakın dönem travmalarıyla öne çıkar.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2304
('e99a7e8a-0beb-5ee5-9706-b2800af5d083', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di civaka kurdî de avahiyên eşîrî di dîrokê de xwedî kîjan fonksiyonê bûne?', 'tora rêxistinbûna civakî, ewlehî, hilberîn û têkiliya siyasî', 'xwarina kevneşopî ya ku bi mirîşk û birincê tê çêkirin', 'ziman, çand, weşangerî, hevgirtin û veguhastina nasnameyê', 'xwarina sebze an pelan a ku bi dagirtinê tê tijîkirin', 'A', 'Avahiyên eşîrî di dîrokê de beşek ji tora hevgirtina civakî û desthilata siyasî bûne.', 'Avahiyên eşîrî di dîrokê de beşek ji tora hevgirtina civakî û desthilata siyasî bûne.', 'Aşiret yapıları tarihsel olarak sosyal dayanışma ve siyasal otorite ağlarının bir parçası olmuştur.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2307
('f1182911-c484-5d35-bea0-e396d39e2b7d', (select id from categories where name = 'Çand'), 'ku-kmr', 'Zimanê kevneşopî yê civaka êzidî kîjan zarava ye?', 'Soranî', 'Zazakî', 'Hewramî', 'Kurmancî', 'D', 'Zimanê kevneşopî yê civaka êzidî kurmancî ye; qewl û beytên olî jî bi vî zaravayî ne.', 'Zimanê kevneşopî yê civaka êzidî kurmancî ye; qewl û beytên olî jî bi vî zaravayî ne.', 'Êzidî topluluğunun geleneksel dili Kurmancîdir; dinî metinler ve ilahiler de bu lehçededir.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2362
('e334b348-14e6-5c1a-8534-e945925fb291', (select id from categories where name = 'Çand'), 'ku-kmr', 'Ji wan serpêhatiyên ku zivistanan têne vegotin re bi Kurmancî bi giştî çi tê gotin?', 'Kurd', 'Amca', 'Çîrok', 'Gelin', 'C', '"Çîrok" ji bo vegotina çîrokan tê gotin; "stran" û "kilam" bi muzîkê ve girêdayî ne, "govend" jî bi reqsê ve girêdayî ye.', '"Çîrok" ji bo vegotina çîrokan tê gotin; "stran" û "kilam" bi muzîkê ve girêdayî ne, "govend" jî bi reqsê ve girêdayî ye.', NULL, 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2388
('d7d3e1f4-562b-5e0a-a1b2-5b9ebda8ec4c', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di çanda herêmê de heyîna efsaneyî ya bi motîfa mar a berbelav kîjan e?', 'efsaneya hespê bibask', 'şahmaran', 'efsaneya keça deryayê', 'efsaneya teyrê dêw', 'B', 'Şahmaran hebûneke efsanewî ya belav e ku nîv mirov nîv mar tê nîşandan.', 'Şahmaran hebûneke efsanewî ya belav e ku nîv mirov nîv mar tê nîşandan.', 'Şahmaran, yarı insan yarı yılan biçiminde tasvir edilen, bölgede yaygın efsanevi bir varlıktır.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2452
('8eeb2f39-2de5-53a9-8331-a5faaa2f1344', (select id from categories where name = 'Çand'), 'ku-kmr', '"Cejna Newrozê" çi ye?', 'Roja şînê', 'Cejna biharê', 'Cejna Qurbanê', 'Roja dirûnê', 'B', 'Newroz cejna biharê ye (cejn = bayram).', 'Newroz cejna biharê ye (cejn = bayram).', '"Cejna Newrozê" Newroz bayramı demektir (cejn = bayram).', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2455
('0c6ea76a-1a24-5e44-9815-4004a3fd742b', (select id from categories where name = 'Çand'), 'ku-kmr', 'Sê rengên bingehîn ên li ser ala Kurdî kîjan in?', 'reş, sor û zer', 'şîn, spî û sor', 'sor, spî û kesk', 'kesk, zer û mor', 'C', 'Di ala kurdî de rengên sor, spî û kesk hene û li navendê rojek heye.', 'Di ala kurdî de rengên sor, spî û kesk hene û li navendê rojek heye.', 'Kürt bayrağında kırmızı, beyaz ve yeşil renkler ile ortada bir güneş bulunur.', 4, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2481
('3ed81ce5-d0e2-5a03-85e6-2be47b930eb1', (select id from categories where name = 'Çand'), 'ku-kmr', 'Kevneşopiya dengbêjiyê berê bi giranî li kîjan cihan zindî dihat hiştin?', 'jiyana herêmî û parvekirin', 'odeyên gund û dîwanxane', 'sor, kesk û zer', 'bi kevneşopiyê re girêdayî ye', 'B', 'Dengbêj bi kevneşopî li odeyên gundan û dîwanan dicivîn û distirandin.', 'Dengbêj bi kevneşopî li odeyên gundan û dîwanan dicivîn û distirandin.', 'Dengbêjler, geleneksel olarak köy odaları ve dîwanlarda toplanıp icra yaparlardı.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2542
('9455333f-9b1b-5e48-bf7a-f36a82f1e61b', (select id from categories where name = 'Çand'), 'ku-kmr', 'Wateya "bav û kal" bi tirkî çi ye?', 'Komşular', 'Misafirler', 'Atalar/ecdat', 'Çocuklar', 'C', '"Bav û kal" bav û kalên mirov, yanî ecdad, îfade dike.', '"Bav û kal" bav û kalên mirov, yanî ecdad, îfade dike.', '"Bav û kal" (baba ve dede) deyimi ataları/ecdadı ifade eder.', 4, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2606
('739a56c7-9218-5787-9764-428fe955e1c3', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di çanda gelêrî ya Kurdî de girîngiya ku ji çiyayan re tê dayîn herî zêde bi çi tê ravekirin?', 'Îranî û gelek gelên din (wek Newrozê)', 'govend tê girtin û li ser agir tê bazdan', 'berxwedana li dijî zilmê û ji nû ve jidayikbûn', 'bi jiyana di erdnîgariya çiyayî de di dirêjahiya dîrokê de', 'D', 'Kurd bi sedsalan e li herêmeke çiyayî dijîn; çiya hem cihê jiyan û debarê hem jî cihê parastinê ye, lewma di çanda gelêrî de cihekî taybet digire.', 'Kurd bi sedsalan e li herêmeke çiyayî dijîn; çiya hem cihê jiyan û debarê hem jî cihê parastinê ye, lewma di çanda gelêrî de cihekî taybet digire.', 'Kürtler yüzyıllardır dağlık bir coğrafyada yaşar; dağlar hem geçim ve yaşam alanı hem de korunak olduğu için halk kültüründe özel bir yere sahiptir.', 3, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2724
('871f9df8-c339-5057-b456-f239051b6cb1', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di Êzidîtiyê de kevneşopiya duakirina ber bi rojê ve çi nîşan dide?', 'pîroziya ku ji ronahiyê/rojê re tê dayîn', 'Melek Tawis û motîfa ronahiyê/rojê', 'bi çanda rojane re girêdayî ye', 'xurtkirina girêdanên civakî', 'A', 'Di kevneşopiya êzidî de pîroziya ku ji roj û ronahiyê re tê dayîn, di şêwazên îbadetê de jî xuya dibe.', 'Di kevneşopiya êzidî de pîroziya ku ji roj û ronahiyê re tê dayîn, di şêwazên îbadetê de jî xuya dibe.', 'Êzidî geleneğinde güneşe/ışığa verilen kutsallık, ibadet biçimlerine de yansır.', 4, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_2782
('c93f5f54-f112-5304-869e-92731756f1b4', (select id from categories where name = 'Çand'), 'ku-kmr', '"şahmaran" çi ye?', 'şêwaza jiyana koçerî û rîtma reqsê', 'reqsa gelêrî ya kevneşopî ya sê-pêyî', 'fîgura mîtolojîk a çanda rojhilat', 'ji bo vegotina ku devkî an ji ber tê veguhastin', 'C', 'Şahmaran di baweriyên gelêrî de şaha maran e; wekî nîvjin nîvmar tê xeyalkirin û sembola zanebûn û bereketê tê dîtin.', 'Şahmaran di baweriyên gelêrî de şaha maran e; wekî nîvjin nîvmar tê xeyalkirin û sembola zanebûn û bereketê tê dîtin.', 'Şahmaran halk inanışında yılanların şahı sayılır; yarı kadın yarı yılan tasvir edilir ve bilgelik ile bereketin simgesi olarak görülür.', 2, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_5969
('fa209787-aae0-5ebe-84bb-414ae578f249', (select id from categories where name = 'Çand'), 'ku-kmr', '"govendên herêmî" çi ne?', 'tora rêxistinbûna civakî, ewlehî, hilberîn û têkiliya siyasî', 'mêvanperwerî û daxwaza avakirina têkiliyê', 'reqsên gelêrî yên ku li her devera Kurdistanê cuda ne', 'govend tê girtin û li ser agir tê banzdan', 'C', 'Govend reqsa komî ye ku bi gelemperî bi destên hevgirtî di xelekê de tê lîstin; nav, muzîk û gavên wê li gorî herêmê diguherin, loma govendên herêmî cuda ne.', 'Govend reqsa komî ye ku bi gelemperî bi destên hevgirtî di xelekê de tê lîstin; nav, muzîk û gavên wê li gorî herêmê diguherin, loma govendên herêmî cuda ne.', 'Govend el ele tutuşup halka halinde oynanan toplu halk dansıdır; müziği, adı ve adımları yöreye göre değiştiği için yöresel govendler farklıdır.', 4, true, 'multiple_choice', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_6020
