('82098c01-6b65-5315-b530-6b4cdbcbef29', (select id from categories where name = 'Çand'), 'ku-kmr', 'Rast e an şaş e: Dengbêjî kevneşopiya vegotina bi deng e ku çîrok û dîrokê bêyî amûrê digihîne.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Dengbêj bêyî amûran bi dengê xwe stran û çîrokan dibêje; bi vî awayî dîrok û bûyerên civakê vediguhêze.', 'Rast e. Dengbêj bêyî amûran bi dengê xwe stran û çîrokan dibêje; bi vî awayî dîrok û bûyerên civakê vediguhêze.', 'Doğru. Dengbêj çalgı kullanmadan sesiyle türküler ve hikâyeler söyler; böylece toplumun tarihini ve olaylarını aktarır.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_can_0000
