('1b2c2955-947e-5fee-8619-b147654792e7', (select id from categories where name = 'Çand'), 'ku-kmr', 'Rast e an şaş e: "destmala govendê" ew destmal e ku sergovend di destê xwe de dihejîne.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Govend reqseke bi komî ya bi destan hevgirtî ye û sergovend bi destmala di destê xwe de rêberî û ahenga rêzê diyar dike.', 'Rast e. Govend reqseke bi komî ya bi destan hevgirtî ye û sergovend bi destmala di destê xwe de rêberî û ahenga rêzê diyar dike.', 'Doğru. Govend (halay) el ele tutuşularak oynanan toplu halk oyunudur; halay başı elindeki mendille sıraya yön verir.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_can_0014
('cd452463-19e7-5b48-bcb9-32a864bc6aa0', (select id from categories where name = 'Çand'), 'ku-kmr', 'Rast e an şaş e: Şabaş kevneşopiya dayîna diyariya pereyî ye di dawet û şahiyan de.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Şabaş di dawet û şahiyan de pere an diyarî dayîna ji bo bûk-zava an hunermendan e; armanc piştgirî û pîrozkirin e.', 'Rast e. Şabaş di dawet û şahiyan de pere an diyarî dayîna ji bo bûk-zava an hunermendan e; armanc piştgirî û pîrozkirin e.', 'Doğru. Şabaş, düğün ve şenliklerde gelin-damada ya da çalgıcılara para hediyesi vermedir; amaç destek ve kutlamadır.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_can_0016
('355b0cfd-5490-5125-9bb3-d266c7b89692', (select id from categories where name = 'Çand'), 'ku-kmr', 'Mêvanperwerî qaîdeya exlaqî ye ku mêvan wek bereketa malê dihesibîne. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Mêvanperwerî di çanda kurdî de nirxeke bingehîn e; mêvan rûmet û bereketa malê tê dîtin, loma malxê xwarin û cih pêşkêş dike.', 'Rast e. Mêvanperwerî di çanda kurdî de nirxeke bingehîn e; mêvan rûmet û bereketa malê tê dîtin, loma malxê xwarin û cih pêşkêş dike.', 'Doğru. Misafirperverlik Kürt kültüründe temel bir değerdir; konuk evin onuru ve bereketi sayılır, ev sahibi ona yiyecek ve yer sunar.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_can_0018
('9dc68080-b3e0-5119-8b4c-f66b434f4deb', (select id from categories where name = 'Çand'), 'ku-kmr', 'Rast e an şaş e: Metelok gotina kurt e ku bi mînakekê pendê digihîne.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Metelok gotineke kurt û tûj e; bi mînakekê şîret an ezmûna jiyanê tîne ziman û dev bi dev tê veguhastin.', 'Rast e. Metelok gotineke kurt û tûj e; bi mînakekê şîret an ezmûna jiyanê tîne ziman û dev bi dev tê veguhastin.', 'Doğru. Metelok, bir örnekle öğüt ya da yaşam deneyimi aktaran kısa ve özlü sözdür; kuşaktan kuşağa sözlü aktarılır.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_can_0020
('24f739d7-0b5e-52ac-b6cb-cecb3f7b626c', (select id from categories where name = 'Çand'), 'ku-kmr', 'Rast e an şaş e: Êzidîtî ew bawerî ye ku li dora Xwedê, heft hebûnên pîroz û Melek Tawis hatiye avakirin.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Êzidîtî baweriyeke kevnar e; li gor wê Xwedê cîhan bi navbeynkariya heft melekên pîroz birêve dibe û Melek Tawis serokê wan e.', 'Rast e. Êzidîtî baweriyeke kevnar e; li gor wê Xwedê cîhan bi navbeynkariya heft melekên pîroz birêve dibe û Melek Tawis serokê wan e.', 'Doğru. Êzidîlik eski bir inançtır; inanışa göre Tanrı dünyayı yedi kutsal melek aracılığıyla yönetir ve Tawûsê Melek bunların başıdır.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_can_0022
('f1e6b70c-dedd-540d-89b5-500ea7d8f4a9', (select id from categories where name = 'Çand'), 'ku-kmr', 'Rast e an şaş e: Êzidîtî ew fîgura navendî ya baweriya êzidî ye ku bi motîfa tawisê tê nîşandan.', 'Rast', 'Şaş', '-', '-', 'B', 'Na — ev ravekirina Melek Tawis e; Êzidîtî ew bawerî ye ku li dora Xwedê, heft hebûnên pîroz û Tawûsê Melek hatiye avakirin.', 'Na — ev ravekirina Melek Tawis e; Êzidîtî ew bawerî ye ku li dora Xwedê, heft hebûnên pîroz û Tawûsê Melek hatiye avakirin.', 'Hayır — bu tanım Melek Tawis''e aittir; Êzidîtî, Tanrı, yedi kutsal varlık ve Tawûsê Melek çevresinde kurulu inançtır.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_can_0023
('35e3d1dc-444f-53f2-a2bf-327968078e5b', (select id from categories where name = 'Çand'), 'ku-kmr', 'Rast e an şaş e: Melek Tawis ew fîgura navendî ya baweriya êzidî ye ku bi motîfa tawisê tê nîşandan.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Melek Tawis di baweriya êzidî de fîgurê herî navendî ye û bi taybetî bi motîfa tawisê tê naskirin û nîşandan.', 'Rast e. Melek Tawis di baweriya êzidî de fîgurê herî navendî ye û bi taybetî bi motîfa tawisê tê naskirin û nîşandan.', 'Doğru. Melek Tawus, Êzidî inancının merkezî figürüdür ve özellikle tavus kuşu motifiyle simgelenir.', 4, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_can_0024
('1eda2f4c-b37f-5d37-808b-3f6ae558076c', (select id from categories where name = 'Çand'), 'ku-kmr', 'Sersal demsala destpêka salê ye ku bi lîstik û şahiyên gundan tê pîrozkirin. Ev rast e an şaş e?', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Sersal bi kurmancî destpêka sala nû ye, ango cejna serê salê ye; bi şahî, lîstik û kombûna malbatan tê pîrozkirin.', 'Rast e. Sersal bi kurmancî destpêka sala nû ye, ango cejna serê salê ye; bi şahî, lîstik û kombûna malbatan tê pîrozkirin.', 'Doğru. Sersal, Kurmancîde yeni yıl, yılbaşı demektir; eğlence, oyunlar ve aile toplantılarıyla kutlanır.', 3, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_can_0026
('cd08c412-cc1c-5cf1-bf31-c1c7be674b97', (select id from categories where name = 'Çand'), 'ku-kmr', 'Rast e an şaş e: "hunera destan" çêkirina bi dest a tişt û xemlan e ku zanîna herêmî hildigire.', 'Rast', 'Şaş', '-', '-', 'A', 'Rast e. Hunera destan bi destan çêkirina tişt û xemlan e; zanîn û şêweya herêmî bi vî karî tê parastin û nifş bi nifş tê veguhastin.', 'Rast e. Hunera destan bi destan çêkirina tişt û xemlan e; zanîn û şêweya herêmî bi vî karî tê parastin û nifş bi nifş tê veguhastin.', 'Doğru. El sanatları, elle eşya ve süs yapma sanatıdır; yerel bilgi ve üslup bu yolla korunup kuşaktan kuşağa aktarılır.', 2, true, 'true_false', NULL, NULL, NULL, NULL, 'approved', 'Kurmancî', 1, now()), -- yerel: offline_tf_can_0028
